//! TLS from certificate files: the handshake, the protocol limits, the key checks, the reload and the bounds.
//!
//! Every certificate is generated by the test into a scratch directory; a client built on `tokio-rustls` trusts the
//! generated certificate and nothing else.

#[path = "support/scratch.rs"]
mod scratch;

use std::net::{IpAddr, SocketAddr};
use std::path::PathBuf;
use std::sync::Arc;

use holzwave_server::limits;
use holzwave_server::proxy::{Admission, Mode, client_address};
use holzwave_server::tls::{self, FileResolver};
use rustls::pki_types::{CertificateDer, ServerName};
use rustls::{ClientConfig, ProtocolVersion, RootCertStore};
use scratch::Scratch;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio_rustls::TlsConnector;

const NAME: &str = "hw.example.test";

/// A generated certificate and key, as PEM texts and as DER.
struct Pair {
    cert_pem: String,
    key_pem: String,
    der: CertificateDer<'static>,
}

fn generate(name: &str) -> Pair {
    let made = rcgen::generate_simple_self_signed(vec![name.to_owned()]).expect("generate a certificate");
    Pair { cert_pem: made.cert.pem(), key_pem: made.signing_key.serialize_pem(), der: made.cert.der().clone() }
}

/// Writes `cert.pem` (0644) and `key.pem` (0600) into the scratch directory.
fn write_pair(dir: &Scratch, pair: &Pair) -> (PathBuf, PathBuf) {
    let cert = dir.write_file("cert.pem", pair.cert_pem.as_bytes(), 0o644);
    let key = dir.write_file("key.pem", pair.key_pem.as_bytes(), 0o600);
    (cert, key)
}

fn client_config(versions: &[&'static rustls::SupportedProtocolVersion], roots: &[&Pair]) -> ClientConfig {
    let mut store = RootCertStore::empty();
    for pair in roots {
        store.add(pair.der.clone()).expect("add the generated certificate as a root");
    }
    ClientConfig::builder_with_provider(Arc::new(rustls::crypto::ring::default_provider()))
        .with_protocol_versions(versions)
        .expect("client protocol versions")
        .with_root_certificates(store)
        .with_no_client_auth()
}

fn tls13_client(roots: &[&Pair]) -> ClientConfig {
    let mut config = client_config(&[&rustls::version::TLS13], roots);
    config.alpn_protocols = vec![b"h2".to_vec(), b"http/1.1".to_vec()];
    config
}

/// A server on 127.0.0.1 that admits, handshakes, writes `hello` and closes, for every connection.
struct Server {
    addr: SocketAddr,
    admission: Admission,
    task: tokio::task::JoinHandle<()>,
}

impl Drop for Server {
    fn drop(&mut self) {
        self.task.abort();
    }
}

async fn serve(resolver: Arc<FileResolver>, handshake_timeout: std::time::Duration) -> Server {
    let config = tls::server_config(resolver, &tls::ALPN).expect("server configuration");
    let acceptor = tls::acceptor(Arc::new(config));
    let admission = Admission::with_defaults(Mode::Files);
    let listener = TcpListener::bind("127.0.0.1:0").await.expect("bind");
    let addr = listener.local_addr().expect("local address");
    let gate = admission.clone();
    let task = tokio::spawn(async move {
        loop {
            let Ok((stream, peer)) = listener.accept().await else { return };
            let Ok(permit) = gate.try_admit(peer.ip()) else { continue };
            let acceptor = acceptor.clone();
            tokio::spawn(async move {
                let _permit = permit;
                if let Ok(mut tls) = tls::accept_tls(&acceptor, stream, handshake_timeout).await {
                    let _ = tls.write_all(b"hello").await;
                    let _ = tls.shutdown().await;
                }
            });
        }
    });
    Server { addr, admission, task }
}

async fn connect(
    server: &Server,
    config: ClientConfig,
) -> std::io::Result<tokio_rustls::client::TlsStream<TcpStream>> {
    let tcp = TcpStream::connect(server.addr).await?;
    let name = ServerName::try_from(NAME).expect("server name");
    TlsConnector::from(Arc::new(config)).connect(name, tcp).await
}

#[tokio::test]
async fn handshake_from_files_is_tls13_with_h2_and_serves_hello() {
    let dir = Scratch::new("tls-handshake");
    let pair = generate(NAME);
    let (cert, key) = write_pair(&dir, &pair);
    let resolver = Arc::new(FileResolver::new(&cert, &key).expect("load the pair"));
    let server = serve(resolver, limits::HANDSHAKE_TIMEOUT).await;

    let mut stream = connect(&server, tls13_client(&[&pair])).await.expect("handshake");
    let mut text = String::new();
    stream.read_to_string(&mut text).await.expect("read hello");
    assert_eq!(text, "hello");

    let (_, conn) = stream.get_ref();
    assert_eq!(conn.protocol_version(), Some(ProtocolVersion::TLSv1_3));
    assert_eq!(conn.alpn_protocol(), Some(&b"h2"[..]));
    let suite = conn.negotiated_cipher_suite().expect("negotiated suite");
    println!(
        "Negotiated: {:?} {:?} ALPN {}",
        conn.protocol_version().expect("version"),
        suite.suite(),
        String::from_utf8_lossy(conn.alpn_protocol().expect("alpn"))
    );

    drop(stream);

    // The same client offering only http/1.1 gets http/1.1.
    let mut http1 = tls13_client(&[&pair]);
    http1.alpn_protocols = vec![b"http/1.1".to_vec()];
    let stream = connect(&server, http1).await.expect("handshake");
    assert_eq!(stream.get_ref().1.alpn_protocol(), Some(&b"http/1.1"[..]));
    drop(stream);

    // Both connections are over, so both slots are free again.
    for _ in 0..100 {
        if server.admission.open_connections() == 0 {
            return;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    panic!("the slots of finished connections were not given back");
}

#[test]
fn the_key_exchange_groups_are_the_ring_providers() {
    let provider = rustls::crypto::ring::default_provider();
    let names: Vec<String> = provider.kx_groups.iter().map(|g| format!("{:?}", g.name())).collect();
    println!("Key exchange: {}", names.join(", "));
    assert!(!names.iter().any(|n| n.contains("MLKEM")), "{names:?}");
}

#[test]
fn the_client_address_outside_the_proxy_mode_is_the_peer() {
    let peer: IpAddr = "203.0.113.9".parse().expect("address");
    for mode in [Mode::Files, Mode::Acme] {
        assert_eq!(client_address(mode, peer, &["198.51.100.7"], &["https"]), Ok(peer));
    }
}
